import{_ as a,o as i,c as s,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Ley de Garantía Médica","description":"","frontmatter":{},"headers":[],"relativePath":"es/44-医疗保障法.md","filePath":"es/44-医疗保障法.md","lastUpdated":null}'),n={name:"es/44-医疗保障法.md"};function d(t,e,r,c,l,u){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="ley-de-garantia-medica" tabindex="-1">Ley de Garantía Médica <a class="header-anchor" href="#ley-de-garantia-medica" aria-label="Permalink to &quot;Ley de Garantía Médica&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>44</td></tr><tr><td>Módulo</td><td>Sistema Legal y Marco de Gobernanza</td></tr><tr><td>Palabras clave</td><td>Derecho a la atención médica, Medicina simbiótica, Tratamiento de lesiones de cultivo, Vida y salud, Sistema de seguro médico</td></tr></tbody></table><h2 id="i-proposito-legislativo-y-principios-basicos" tabindex="-1">I. Propósito Legislativo y Principios Básicos <a class="header-anchor" href="#i-proposito-legislativo-y-principios-basicos" aria-label="Permalink to &quot;I. Propósito Legislativo y Principios Básicos&quot;">​</a></h2><p>La <em>Ley de Garantía Médica</em> es una de las cinco leyes complementarias de la Civilización Simbiótica del Ancla. Su objetivo es garantizar el derecho a la salud y a la atención médica de todas las vidas dentro del Universo Hengyuan, establecer un sistema médico simbiótico que cubra a todas las razas, y asegurar que cada vida pueda recibir un tratamiento oportuno y eficaz ante lesiones o enfermedades.</p><p>Esta Ley establece los siguientes principios básicos:</p><table tabindex="0"><thead><tr><th>Principio</th><th>Contenido</th></tr></thead><tbody><tr><td>Prioridad de la Salud</td><td>La vida y la salud son la base de toda evolución; el estado y la civilización sitúan la protección de la vida y la salud en una posición prioritaria</td></tr><tr><td>Cobertura Universal</td><td>La garantía médica cubre a todas las vidas, sin importar raza, cultivo, origen o situación económica</td></tr><tr><td>Atención Jerarquizada</td><td>Establecer un sistema de atención de tres niveles — medicina básica, medicina regional, medicina avanzada — asignando racionalmente los recursos médicos</td></tr><tr><td>Combinación de Prevención y Tratamiento</td><td>Prevención primero, combinación de prevención y tratamiento; dar importancia a la prevención y rehabilitación de las lesiones de cultivo</td></tr><tr><td>Adaptación a Otras Razas</td><td>Proporcionar planes médicos adaptados a las características fisiológicas de las distintas razas; prohibir la aplicación uniforme de estándares humanos</td></tr><tr><td>Atributo de Interés Público</td><td>Los servicios médicos básicos tienen atributo de interés público; el derecho al tratamiento de las vidas no debe ser privado con fines de lucro</td></tr></tbody></table><h2 id="ii-garantias-legales-del-derecho-a-la-vida-y-la-salud" tabindex="-1">II. Garantías Legales del Derecho a la Vida y la Salud <a class="header-anchor" href="#ii-garantias-legales-del-derecho-a-la-vida-y-la-salud" aria-label="Permalink to &quot;II. Garantías Legales del Derecho a la Vida y la Salud&quot;">​</a></h2><p>Esta Ley estipula explícitamente que el derecho a la vida y la salud es un derecho básico conferido a cada vida por la Constitución Simbiótica, que incluye específicamente:</p><ol><li><strong>Derecho a la Atención Médica Básica</strong>: Cada vida tiene derecho a recibir servicios médicos básicos gratuitos, incluidos diagnóstico y tratamiento de enfermedades comunes, medicamentos básicos, exámenes físicos de rutina, etc.</li><li><strong>Derecho a la Atención de Emergencia</strong>: Cada vida tiene derecho a recibir atención de emergencia ante lesiones o enfermedades repentinas; las instituciones médicas no deben negar la atención de emergencia por ningún motivo.</li><li><strong>Derecho al Tratamiento de Lesiones de Cultivo</strong>: Los cultivadores que sufran trastornos energéticos, daños en los meridianos, desviación de cultivo y otras lesiones durante el proceso de cultivo tienen derecho a recibir tratamiento profesional.</li><li><strong>Derecho al Consentimiento Informado</strong>: Los pacientes tienen derecho a conocer su propia condición, el plan de tratamiento, los riesgos y el pronóstico, y derecho a elegir o rechazar los planes de tratamiento.</li><li><strong>Derecho a la Protección de la Privacidad</strong>: La información médica y los datos corporales de los pacientes están protegidos por la ley; sin el consentimiento del paciente, no deben divulgarse ni utilizarse para otros fines.</li><li><strong>Derecho a la Garantía de Rehabilitación</strong>: Los pacientes heridos y enfermos tienen derecho a recibir tratamiento de rehabilitación y dispositivos de asistencia, ayudándoles a recuperar sus capacidades laborales y de vida.</li></ol><h2 id="iii-arquitectura-del-sistema-medico-simbiotico" tabindex="-1">III. Arquitectura del Sistema Médico Simbiótico <a class="header-anchor" href="#iii-arquitectura-del-sistema-medico-simbiotico" aria-label="Permalink to &quot;III. Arquitectura del Sistema Médico Simbiótico&quot;">​</a></h2><p>El sistema médico de la Civilización Simbiótica del Ancla se divide en tres niveles, con mecanismos de derivación y colaboración establecidos entre los niveles:</p><table tabindex="0"><thead><tr><th>Nivel</th><th>Nombre</th><th>Funciones</th><th>Cobertura</th></tr></thead><tbody><tr><td>Primer nivel</td><td>Puesto Médico de Base</td><td>Diagnóstico y tratamiento de enfermedades comunes, atención preventiva, exámenes básicos, transporte de emergencia</td><td>Comunidades/pueblos/planos pequeños</td></tr><tr><td>Segundo nivel</td><td>Centro Médico Regional</td><td>Diagnóstico y tratamiento especializado, tratamiento quirúrgico, manejo inicial de lesiones de cultivo, rehabilitación</td><td>Ciudades/regiones/planos medianos</td></tr><tr><td>Tercer nivel</td><td>Hospital General Médico Avanzado</td><td>Enfermedades difíciles y graves, lesiones de cultivo avanzadas, enfermedades del dominio de la conciencia, enfermedades difíciles interraciales</td><td>Núcleo civilizacional/planos grandes</td></tr></tbody></table><p>Además, se establece una &quot;Especialidad de Lesiones de Cultivo&quot;: maneja específicamente todo tipo de lesiones durante el cultivo, incluida la sobrecarga energética, la ruptura de meridianos, la invasión de demonios del corazón, el trauma del alma, etc., equipada con personal médico versado en las leyes del cultivo.</p><h2 id="iv-fondo-de-garantia-medica" tabindex="-1">IV. Fondo de Garantía Médica <a class="header-anchor" href="#iv-fondo-de-garantia-medica" aria-label="Permalink to &quot;IV. Fondo de Garantía Médica&quot;">​</a></h2><p>El Fondo de Garantía Médica es la base económica del funcionamiento del sistema médico simbiótico, con fuentes que incluyen:</p><ul><li>Asignaciones de la acumulación pública (fuente principal)</li><li>Retenciones de garantía médica en el Mecanismo de Contratación Conjunta de Producción</li><li>Donaciones sociales</li><li>Rendimientos de inversiones del fondo</li></ul><p>El alcance de pagos del fondo incluye: costos de servicios médicos básicos, costos de atención de emergencia, costos de tratamiento de lesiones de cultivo, costos de medicamentos básicos, costos de rehabilitación, etc. Los pacientes solo necesitan pagar una pequeña cantidad de gastos de su bolsillo, con reducciones y exenciones para quienes están en dificultades económicas.</p><h2 id="v-instituciones-medicas-y-personal-medico" tabindex="-1">V. Instituciones Médicas y Personal Médico <a class="header-anchor" href="#v-instituciones-medicas-y-personal-medico" aria-label="Permalink to &quot;V. Instituciones Médicas y Personal Médico&quot;">​</a></h2><ul><li><strong>Instituciones Médicas Públicas</strong>: Establecidas por el estado o la comunidad civilizacional, asumen los servicios médicos básicos y las funciones de salud pública, con financiamiento garantizado por el Fondo de Garantía Médica.</li><li><strong>Instituciones Médicas Privadas</strong>: Establecidas por fuerzas sociales conforme a la ley; pueden proporcionar servicios médicos de alta gama, pero deben aceptar la supervisión de las autoridades médicas competentes y no deben rechazar a pacientes en emergencia.</li><li><strong>Instituciones Médicas para Otras Razas</strong>: Instituciones médicas especializadas establecidas para las necesidades fisiológicas de razas particulares, equipadas con personal médico de otras razas.</li><li><strong>Derechos y Obligaciones del Personal Médico</strong>: El personal médico goza de derechos como protección del ejercicio, remuneración razonable y formación profesional, al tiempo que asume obligaciones como salvar a los moribundos y curar a los heridos, respetar a los pacientes y guardar el secreto médico.</li></ul><h2 id="vi-salud-publica-y-prevencion" tabindex="-1">VI. Salud Pública y Prevención <a class="header-anchor" href="#vi-salud-publica-y-prevencion" aria-label="Permalink to &quot;VI. Salud Pública y Prevención&quot;">​</a></h2><p>El estado establece un sistema de salud pública, cumpliendo las siguientes funciones:</p><ol><li>Vigilancia y prevención de enfermedades infecciosas, establecimiento de un mecanismo de alerta temprana de epidemias transplanares.</li><li>Exámenes de salud universales y gestión de expedientes de salud.</li><li>Divulgación de la seguridad del cultivo y orientación sobre la prevención de lesiones de cultivo.</li><li>Supervisión de la higiene ambiental y de la seguridad de alimentos y medicamentos.</li><li>Respuesta de emergencia ante eventos de salud pública.</li></ol><h2 id="vii-responsabilidad-legal" tabindex="-1">VII. Responsabilidad Legal <a class="header-anchor" href="#vii-responsabilidad-legal" aria-label="Permalink to &quot;VII. Responsabilidad Legal&quot;">​</a></h2><p>Los actos que violen las disposiciones de esta Ley asumirán las siguientes responsabilidades según la gravedad de las circunstancias:</p><ul><li>Las instituciones médicas que rechacen pacientes en emergencia serán ordenadas a rectificar y multadas; si se producen consecuencias graves, se revocan sus licencias de ejercicio.</li><li>El personal médico cuya negligencia grave cause daño a los pacientes asumirá responsabilidad de indemnización; en casos graves, se revocan sus calificaciones de ejercicio.</li><li>Las instituciones médicas que cobren en violación de las normas o proporcionen tratamientos excesivos serán ordenadas a devolver las tarifas y multadas.</li><li>Quienes divulguen la privacidad médica de los pacientes asumirán indemnización por daño moral; en casos graves, se persigue responsabilidad penal.</li><li>Quienes produzcan y vendan medicamentos falsificados o de calidad inferior tendrán confiscadas sus ganancias ilegales y serán multados; si constituye delito, se persigue responsabilidad penal.</li></ul><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La <em>Ley de Garantía Médica</em> es la manifestación de la filosofía de &quot;un camino para todos&quot; de la Civilización Simbiótica del Ancla en el ámbito de la salud. Al establecer un sistema de garantía médica de cobertura universal, crear una especialidad de lesiones de cultivo y garantizar el derecho a la atención de emergencia, asegura que cada vida pueda recibir tratamiento oportuno ante lesiones o enfermedades, sentando una base sólida de salud para el avance conjunto de las Diez Mil Razas.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitución Simbiótica: Principios Generales)</li><li>38-共生医疗体系 (Sistema Médico Simbiótico)</li><li>45-住房保障法 (Ley de Garantía de Vivienda)</li><li>08-人人有路保障体系 (Sistema de Garantía de un Camino para Todos)</li></ul>',29)])])}const b=a(n,[["render",d]]);export{p as __pageData,b as default};
